    return Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      Number(hours),
      Number(minutes),
      Number(seconds)
    );
  }

  const parsed = Date.parse(asText);
  return Number.isNaN(parsed) ? null : parsed;
