  if (!value) return EMPTY_VALUE;
  const normalized = String(value).trim();
  if (!normalized) return EMPTY_VALUE;

  const parts = normalized.split(/\s+/);
  if (parts.length < 2) return normalized;
  return `${parts[0][0]}. ${parts[parts.length - 1]}`;
};

