import React, { useCallback, useEffect, useMemo, useState } from "react";
import { withTranslation } from "react-i18next";
import { useLocation } from "react-router-dom";
import Header from "../../parts/header/Header";
import DataTable from "../../components/DataTable/DataTable";
import Drawer from "../../components/Drawer/Drawer";
import columns from "./messageColumns";
import Notification from "../../components/Notification/Notification";
import {
  OUTGOING,
  OUTGOING_ERRORS,
  OUTGOING_FOR_ENTRY,
  OUTGOING_FOR_REWORK,
  OUTGOING_FOR_VERIFICATION,
  OUTGOING_MY_ORDERS,
  OUTGOING_MY_ORDERS_FOR_REWORK,
} from "../../components/routes";
import {
  getAll,
  getErrors,
  getForEntry,
  getForRework,
  getForVerification,
  getMyOrders,
  getMyOrdersForRework,
  searchArchive as searchOutgoingArchive,
} from "../../services/outgoingService/service";
import {
  extractTransactionItems,
  mapTransactionListItems,
} from "../../utils/transactionListMapper";

const OUTGOING_ROUTE_SETTINGS = [
  {
    path: OUTGOING_MY_ORDERS_FOR_REWORK,
    titleKey: "sidebar:forRework",
    titleDefault: "Za doradu",
    loadData: getMyOrdersForRework,
    fallbackLoadData: getAll,
  },
  {
    path: OUTGOING_MY_ORDERS,
    titleKey: "sidebar:allMyOrders",
    titleDefault: "Sve moje poruke",
    loadData: getMyOrders,
    fallbackLoadData: getAll,
  },
  {
    path: OUTGOING_FOR_ENTRY,
    titleKey: "sidebar:forEntry",
    titleDefault: "Za unos",
    loadData: getForEntry,
    fallbackLoadData: getAll,
  },
  {
    path: OUTGOING_FOR_REWORK,
    titleKey: "sidebar:forRework",
    titleDefault: "Za doradu",
    loadData: getForRework,
    fallbackLoadData: getAll,
  },
  {
    path: OUTGOING_FOR_VERIFICATION,
    titleKey: "sidebar:forVerification",
    titleDefault: "Za verifikaciju",
    loadData: getForVerification,
    fallbackLoadData: getAll,
  },
  {
    path: OUTGOING_ERRORS,
    titleKey: "sidebar:errors",
    titleDefault: "GreÅ¡ke",
    loadData: getErrors,
    fallbackLoadData: getAll,
  },
  {
    path: OUTGOING,
    titleKey: "sidebar:allOrders",
    titleDefault: "Sve poruke",
    loadData: getAll,
  },
];

const normalizePath = (path) => {
  if (!path) return "";
  if (path.length > 1 && path.endsWith("/")) return path.slice(0, -1);
  return path;
};

const resolveRouteSettings = (pathname) => {
  const normalizedPath = normalizePath(pathname);
  const matchedRoute = OUTGOING_ROUTE_SETTINGS.find(
    (route) => normalizePath(route.path) === normalizedPath
  );
  return (
    matchedRoute ||
    OUTGOING_ROUTE_SETTINGS.find((route) => route.path === OUTGOING) ||
    OUTGOING_ROUTE_SETTINGS[0]
  );
};

const OutgoingBase = ({ t }) => {
  const location = useLocation();
  const { titleKey, titleDefault, loadData, fallbackLoadData } = useMemo(
    () => resolveRouteSettings(location.pathname),
    [location.pathname]
  );
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState(null);

  const refreshCurrentRouteItems = useCallback(async () => {
    try {
      const response = await loadData();
      const mappedItems = mapTransactionListItems(
        extractTransactionItems(response)
      );
      setItems(mappedItems);
      return;
    } catch (primaryError) {
      if (!fallbackLoadData) {
        return;
      }
    }

    try {
      const response = await fallbackLoadData();
      const mappedItems = mapTransactionListItems(
        extractTransactionItems(response)
      );
      setItems(mappedItems);
    } catch (fallbackError) {
      // Keep current optimistic row state if refresh fails.
    }
  }, [fallbackLoadData, loadData]);

  const handleArchiveSearch = useCallback(
    async (criteria = {}) => {
      setLoading(true);
      try {
        const response = await searchOutgoingArchive(criteria);
        const mappedItems = mapTransactionListItems(
          extractTransactionItems(response)
        );
        setItems(mappedItems);
        return true;
      } catch (error) {
        Notification(
          t("common:errorTitle", { defaultValue: "Greska" }),
          error?.response?.data?.message ||
            t("notification:outgoing:archiveSearchMessage", {
              defaultValue: "Neuspesna pretraga arhive.",
            }),
          "error",
          "topRight"
        );
        return false;
      } finally {
        setLoading(false);
      }
    },
    [t]
  );

  const handleView = (record) => {
    if (record?.canOpenDrawer === false) {
      return;
    }
    setSelectedOrder(record || null);
    setIsDrawerOpen(true);
  };

  const handleCloseDrawer = () => {
    setIsDrawerOpen(false);
  };

  const handleOrderUpdated = (updatedOrder) => {
    if (!updatedOrder || updatedOrder.id === null || updatedOrder.id === undefined) {
      return;
    }

    setSelectedOrder(updatedOrder);
    setItems((currentItems) =>
      currentItems.map((item) => {
        if (String(item?.id) !== String(updatedOrder.id)) {
          return item;
        }
        return {
          ...item,
          ...updatedOrder,
          statusCode: updatedOrder.statusCode || item?.statusCode,
          status: updatedOrder.status || item?.status,
          _raw: {
            ...(item?._raw || {}),
            ...(updatedOrder?._raw || {}),
          },
        };
      })
    );

    void refreshCurrentRouteItems();
  };

  useEffect(() => {
    if (top !== self) {
      top.location = self.location;
    }

    let cancelled = false;

    const fetchOutgoing = async () => {
      setLoading(true);
      try {
        const response = await loadData();
        const mappedItems = mapTransactionListItems(
          extractTransactionItems(response)
        );
        if (!cancelled) {
          setItems(mappedItems);
        }
      } catch (primaryError) {
        if (!fallbackLoadData) {
          if (!cancelled) {
            Notification(
              t("notification:outgoing:error", { defaultValue: "Greska" }),
              t("notification:outgoing:message", {
                defaultValue: "Neuspesno ucitavanje outgoing podataka.",
              }),
              "error",
              "topRight"
            );
          }
          return;
        }

        try {
          const response = await fallbackLoadData();
          const mappedItems = mapTransactionListItems(
            extractTransactionItems(response)
          );
          if (!cancelled) {
            setItems(mappedItems);
          }
        } catch (fallbackError) {
          if (!cancelled) {
            Notification(
              t("notification:outgoing:error", { defaultValue: "Greska" }),
              t("notification:outgoing:message", {
                defaultValue: "Neuspesno ucitavanje outgoing podataka.",
              }),
              "error",
              "topRight"
            );
          }
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    fetchOutgoing();

    return () => {
      cancelled = true;
    };
  }, [fallbackLoadData, loadData, t]);

  return (
    <>
      <Header title={t(titleKey, { defaultValue: titleDefault })} />
      <DataTable
        items={items}
        columns={columns}
        loading={loading}
        onView={handleView}
        onArchiveSearch={handleArchiveSearch}
      />
      <Drawer
        open={isDrawerOpen}
        onClose={handleCloseDrawer}
        selectedOrder={selectedOrder}
        onOrderUpdated={handleOrderUpdated}
      />
    </>
  );
};

export default withTranslation(["privatePage"])(OutgoingBase);

